16. // GetCertPool gets a cert pool for the given CA or CAFile.
17. func GetCertPool(ca, caFile string) (*x509.CertPool, error) {
18. 	ctx := context.TODO()
19. 	rootCAs, err := x509.SystemCertPool()
20. 	if err != nil {
21. 		log.Error(ctx).Err(err).Msg("pkg/cryptutil: failed getting system cert pool making new one")
22. 		rootCAs = x509.NewCertPool()
23. 	}
24. 	if ca == "" && caFile == "" {
25. 		return rootCAs, nil
26. 	}
27. 
28. 	var data []byte
29. 	if ca != "" {
30. 		data, err = base64.StdEncoding.DecodeString(ca)
31. 		if err != nil {
32. 			return nil, fmt.Errorf("failed to decode base64-encoded certificate authority: %w", err)
33. 		}
34. 	} else {
35. 		data, err = os.ReadFile(caFile)
36. 		if err != nil {
37. 			return nil, fmt.Errorf("failed to read certificate authority file (%s): %w", caFile, err)
38. 		}
39. 	}
40. 	if ok := rootCAs.AppendCertsFromPEM(data); !ok {
41. 		return nil, fmt.Errorf("failed to append any PEM-encoded certificates")
42. 	}
43. 	log.Debug(ctx).Msg("pkg/cryptutil: added custom certificate authority")
44. 	return rootCAs, nil
45. }
