47. // GetCertificateForDomain returns the tls Certificate which matches the given domain name.
48. // It should handle both exact matches and wildcard matches. If none of those match, the first certificate will be used.
49. // Finally if there are no matching certificates one will be generated.
50. func GetCertificateForDomain(certificates []tls.Certificate, domain string) (*tls.Certificate, error) {
51. 	// first try a direct name match
52. 	for i := range certificates {
53. 		if matchesDomain(&certificates[i], domain) {
54. 			return &certificates[i], nil
55. 		}
56. 	}
57. 
58. 	log.Error(context.Background()).
59. 		Str("domain", domain).
60. 		Msg("cryptutil: no TLS certificate found for domain, using self-signed certificate")
61. 
62. 	// finally fall back to a generated, self-signed certificate
63. 	return GenerateSelfSignedCertificate(domain)
64. }
65. 
66. func matchesDomain(cert *tls.Certificate, domain string) bool {
67. 	if cert == nil || len(cert.Certificate) == 0 {
68. 		return false
69. 	}
70. 
71. 	xcert, err := x509.ParseCertificate(cert.Certificate[0])
72. 	if err != nil {
