1. // Package autocert implements automatic management of TLS certificates.
2. package autocert
3. 
4. import (
5. 	"context"
6. 	"encoding/base64"
7. 	"errors"
8. 	"fmt"
9. 	"net/http"
10. 	"sort"
11. 	"sync"
12. 	"sync/atomic"
13. 	"time"
14. 
15. 	"github.com/caddyserver/certmagic"
16. 	"github.com/mholt/acmez/acme"
17. 	"github.com/rs/zerolog"
18. 	"go.uber.org/zap"
19. 
20. 	"github.com/pomerium/pomerium/config"
21. 	"github.com/pomerium/pomerium/internal/httputil"
22. 	"github.com/pomerium/pomerium/internal/log"
23. 	"github.com/pomerium/pomerium/internal/telemetry/metrics"
24. 	"github.com/pomerium/pomerium/pkg/cryptutil"
25. )
26. 
27. var (
28. 	errObtainCertFailed = errors.New("obtain cert failed")
29. 	errRenewCertFailed  = errors.New("renew cert failed")
30. 
31. 	// RenewCert is not thread-safe
32. 	renewCertLock sync.Mutex
33. )
34. 
35. const (
36. 	ocspRespCacheSize = 50000
37. 	renewalInterval   = time.Minute * 10
38. 	renewalTimeout    = time.Hour
39. )
40. 
41. // Manager manages TLS certificates.
42. type Manager struct {
43. 	src          config.Source
44. 	acmeTemplate certmagic.ACMEManager
45. 
46. 	mu        sync.RWMutex
47. 	config    *config.Config
48. 	certmagic *certmagic.Config
49. 	acmeMgr   atomic.Value
50. 	srv       *http.Server
51. 
52. 	*ocspCache
53. 
54. 	config.ChangeDispatcher
55. }
56. 
57. // New creates a new autocert manager.
58. func New(src config.Source) (*Manager, error) {
59. 	return newManager(context.Background(), src, certmagic.DefaultACME, renewalInterval)
60. }
61. 
62. func newManager(ctx context.Context,
63. 	src config.Source,
64. 	acmeTemplate certmagic.ACMEManager,
65. 	checkInterval time.Duration,
66. ) (*Manager, error) {
67. 	ctx = log.WithContext(ctx, func(c zerolog.Context) zerolog.Context {
68. 		return c.Str("service", "autocert-manager")
69. 	})
70. 
71. 	ocspRespCache, err := newOCSPCache(ocspRespCacheSize)
72. 	if err != nil {
73. 		return nil, err
74. 	}
75. 
76. 	certmagicConfig := certmagic.NewDefault()
77. 	// set certmagic default storage cache, otherwise cert renewal loop will be based off
78. 	// certmagic's own default location
79. 	certmagicConfig.Storage = &certmagic.FileStorage{
80. 		Path: src.GetConfig().Options.AutocertOptions.Folder,
81. 	}
82. 
83. 	logger := log.ZapLogger().With(zap.String("service", "autocert"))
84. 	certmagicConfig.Logger = logger
85. 	acmeTemplate.Logger = logger
86. 
87. 	mgr := &Manager{
88. 		src:          src,
89. 		acmeTemplate: acmeTemplate,
90. 		certmagic:    certmagicConfig,
91. 		ocspCache:    ocspRespCache,
92. 	}
93. 	err = mgr.update(ctx, src.GetConfig())
94. 	if err != nil {
95. 		return nil, err
96. 	}
97. 	mgr.src.OnConfigChange(ctx, func(ctx context.Context, cfg *config.Config) {
98. 		err := mgr.update(ctx, cfg)
99. 		if err != nil {
100. 			log.Error(ctx).Err(err).Msg("autocert: error updating config")
101. 			return
102. 		}
103. 
104. 		cfg = mgr.GetConfig()
105. 		mgr.Trigger(ctx, cfg)
106. 	})
107. 	go func() {
108. 		ticker := time.NewTicker(checkInterval)
109. 		defer ticker.Stop()
110. 
111. 		for {
112. 			select {
113. 			case <-ctx.Done():
114. 				return
115. 			case <-ticker.C:
116. 				err := mgr.renewConfigCerts(ctx)
117. 				if err != nil {
118. 					log.Error(ctx).Err(err).Msg("autocert: error updating config")
119. 					return
120. 				}
121. 			}
122. 		}
123. 	}()
124. 	return mgr, nil
125. }
126. 
127. func (mgr *Manager) getCertMagicConfig(cfg *config.Config) (*certmagic.Config, error) {
128. 	mgr.certmagic.MustStaple = cfg.Options.AutocertOptions.MustStaple
129. 	mgr.certmagic.OnDemand = nil // disable on-demand
130. 	mgr.certmagic.Storage = &certmagic.FileStorage{Path: cfg.Options.AutocertOptions.Folder}
131. 	certs, err := cfg.AllCertificates()
132. 	if err != nil {
133. 		return nil, err
134. 	}
135. 	// add existing certs to the cache, and staple OCSP
136. 	for _, cert := range certs {
137. 		if err := mgr.certmagic.CacheUnmanagedTLSCertificate(cert, nil); err != nil {
138. 			return nil, fmt.Errorf("config: failed caching cert: %w", err)
139. 		}
140. 	}
141. 	acmeMgr := certmagic.NewACMEManager(mgr.certmagic, mgr.acmeTemplate)
142. 	err = configureCertificateAuthority(acmeMgr, cfg.Options.AutocertOptions)
143. 	if err != nil {
144. 		return nil, err
145. 	}
146. 	err = configureExternalAccountBinding(acmeMgr, cfg.Options.AutocertOptions)
147. 	if err != nil {
148. 		return nil, err
149. 	}
150. 	err = configureTrustedRoots(acmeMgr, cfg.Options.AutocertOptions)
151. 	if err != nil {
152. 		return nil, err
153. 	}
154. 	acmeMgr.DisableTLSALPNChallenge = true
155. 	mgr.certmagic.Issuers = []certmagic.Issuer{acmeMgr}
156. 	mgr.acmeMgr.Store(acmeMgr)
157. 
158. 	return mgr.certmagic, nil
159. }
160. 
161. func (mgr *Manager) renewConfigCerts(ctx context.Context) error {
162. 	ctx, cancel := context.WithTimeout(ctx, renewalTimeout)
163. 	defer cancel()
164. 
165. 	mgr.mu.Lock()
166. 	defer mgr.mu.Unlock()
167. 
168. 	cfg := mgr.config
169. 	cm, err := mgr.getCertMagicConfig(cfg)
170. 	if err != nil {
171. 		return err
172. 	}
173. 
174. 	needsReload := false
175. 	var renew, ocsp []string
176. 	log.Debug(ctx).Strs("domains", sourceHostnames(cfg)).Msg("checking domains")
177. 	for _, domain := range sourceHostnames(cfg) {
178. 		cert, err := cm.CacheManagedCertificate(domain)
179. 		if err != nil {
180. 			// this happens for unmanaged certificates
181. 			continue
182. 		}
183. 		if cert.NeedsRenewal(cm) {
184. 			renew = append(renew, domain)
185. 			needsReload = true
186. 		}
187. 		if mgr.ocspCache.updated(domain, cert.OCSPStaple) {
188. 			ocsp = append(ocsp, domain)
189. 			needsReload = true
190. 		}
191. 	}
192. 	if !needsReload {
193. 		return nil
194. 	}
195. 
196. 	ctx = log.WithContext(ctx, func(c zerolog.Context) zerolog.Context {
197. 		if len(renew) > 0 {
198. 			c = c.Strs("renew_domains", renew)
199. 		}
200. 		if len(ocsp) > 0 {
201. 			c = c.Strs("ocsp_refresh", ocsp)
202. 		}
203. 		return c
204. 	})
205. 	log.Info(ctx).Msg("updating certificates")
206. 
207. 	cfg = mgr.src.GetConfig().Clone()
208. 	mgr.updateServer(ctx, cfg)
209. 	if err := mgr.updateAutocert(ctx, cfg); err != nil {
210. 		return err
211. 	}
212. 
213. 	mgr.config = cfg
214. 	mgr.Trigger(ctx, cfg)
215. 	return nil
216. }
217. 
218. func (mgr *Manager) update(ctx context.Context, cfg *config.Config) error {
219. 	cfg = cfg.Clone()
220. 
221. 	mgr.mu.Lock()
222. 	defer mgr.mu.Unlock()
223. 	defer func() { mgr.config = cfg }()
224. 
225. 	mgr.updateServer(ctx, cfg)
226. 	return mgr.updateAutocert(ctx, cfg)
227. }
228. 
229. // obtainCert obtains a certificate for given domain, use cached manager if cert exists there.
230. func (mgr *Manager) obtainCert(ctx context.Context, domain string, cm *certmagic.Config) (certmagic.Certificate, error) {
231. 	cert, err := cm.CacheManagedCertificate(domain)
232. 	if err != nil {
233. 		log.Info(ctx).Str("domain", domain).Msg("obtaining certificate")
234. 		err = cm.ObtainCertSync(ctx, domain)
235. 		if err != nil {
236. 			log.Error(ctx).Err(err).Msg("autocert failed to obtain client certificate")
237. 			return certmagic.Certificate{}, errObtainCertFailed
238. 		}
239. 		metrics.RecordAutocertRenewal()
240. 		cert, err = cm.CacheManagedCertificate(domain)
241. 	}
242. 	return cert, err
243. }
244. 
245. // renewCert attempts to renew given certificate.
246. func (mgr *Manager) renewCert(ctx context.Context, domain string, cert certmagic.Certificate, cm *certmagic.Config) (certmagic.Certificate, error) {
247. 	expired := time.Now().After(cert.Leaf.NotAfter)
248. 	log.Info(ctx).Str("domain", domain).Msg("renewing certificate")
249. 	renewCertLock.Lock()
250. 	err := cm.RenewCertSync(ctx, domain, false)
251. 	renewCertLock.Unlock()
252. 	if err != nil {
253. 		if expired {
254. 			return certmagic.Certificate{}, errRenewCertFailed
255. 		}
256. 		log.Warn(ctx).Err(err).Msg("renew client certificated failed, use existing cert")
257. 	}
258. 	return cm.CacheManagedCertificate(domain)
259. }
260. 
261. func (mgr *Manager) updateAutocert(ctx context.Context, cfg *config.Config) error {
262. 	if !cfg.Options.AutocertOptions.Enable {
263. 		return nil
264. 	}
265. 
266. 	cm, err := mgr.getCertMagicConfig(cfg)
267. 	if err != nil {
268. 		return err
269. 	}
270. 
271. 	for _, domain := range sourceHostnames(cfg) {
272. 		cert, err := mgr.obtainCert(ctx, domain, cm)
273. 		if err != nil && errors.Is(err, errObtainCertFailed) {
274. 			return fmt.Errorf("autocert: failed to obtain client certificate: %w", err)
275. 		}
276. 		if err == nil && cert.NeedsRenewal(cm) {
277. 			cert, err = mgr.renewCert(ctx, domain, cert, cm)
278. 		}
279. 		if err != nil && errors.Is(err, errRenewCertFailed) {
280. 			return fmt.Errorf("autocert: failed to renew client certificate: %w", err)
281. 		}
282. 		if err != nil {
283. 			log.Error(ctx).Err(err).Msg("autocert: failed to obtain client certificate")
284. 			continue
285. 		}
286. 
287. 		log.Info(ctx).Strs("names", cert.Names).Msg("autocert: added certificate")
288. 		cfg.AutoCertificates = append(cfg.AutoCertificates, cert.Certificate)
289. 	}
290. 
291. 	metrics.RecordAutocertCertificates(cfg.AutoCertificates)
292. 
293. 	return nil
294. }
295. 
296. func (mgr *Manager) updateServer(ctx context.Context, cfg *config.Config) {
297. 	if mgr.srv != nil {
298. 		// nothing to do if the address hasn't changed
299. 		if mgr.srv.Addr == cfg.Options.HTTPRedirectAddr {
300. 			return
301. 		}
302. 		// close immediately, don't care about the error
303. 		_ = mgr.srv.Close()
304. 		mgr.srv = nil
305. 	}
306. 
307. 	if cfg.Options.HTTPRedirectAddr == "" {
308. 		return
309. 	}
310. 
311. 	redirect := httputil.RedirectHandler()
312. 
313. 	hsrv := &http.Server{
314. 		Addr: cfg.Options.HTTPRedirectAddr,
315. 		Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
316. 			if mgr.handleHTTPChallenge(w, r) {
317. 				return
318. 			}
319. 			redirect.ServeHTTP(w, r)
320. 		}),
321. 	}
322. 	go func() {
323. 		log.Info(ctx).Str("addr", hsrv.Addr).Msg("starting http redirect server")
324. 		err := hsrv.ListenAndServe()
325. 		if err != nil {
326. 			log.Error(ctx).Err(err).Msg("failed to run http redirect server")
327. 		}
328. 	}()
329. 	mgr.srv = hsrv
330. }
331. 
332. func (mgr *Manager) handleHTTPChallenge(w http.ResponseWriter, r *http.Request) bool {
333. 	obj := mgr.acmeMgr.Load()
334. 	if obj == nil {
335. 		return false
336. 	}
337. 	acmeMgr := obj.(*certmagic.ACMEManager)
338. 	return acmeMgr.HandleHTTPChallenge(w, r)
339. }
340. 
341. // GetConfig gets the config.
342. func (mgr *Manager) GetConfig() *config.Config {
343. 	mgr.mu.RLock()
344. 	defer mgr.mu.RUnlock()
345. 
346. 	return mgr.config
347. }
348. 
349. // configureCertificateAuthority configures the acmeMgr ACME Certificate Authority settings.
350. func configureCertificateAuthority(acmeMgr *certmagic.ACMEManager, opts config.AutocertOptions) error {
351. 	acmeMgr.Agreed = true
352. 	if opts.UseStaging {
353. 		acmeMgr.CA = acmeMgr.TestCA
354. 	}
355. 	if opts.CA != "" {
356. 		acmeMgr.CA = opts.CA // when a CA is specified, it overrides the staging setting
357. 	}
358. 	if opts.Email != "" {
359. 		acmeMgr.Email = opts.Email
360. 	}
361. 	return nil
362. }
363. 
364. // configureExternalAccountBinding configures the acmeMgr ACME External Account Binding settings.
365. func configureExternalAccountBinding(acmeMgr *certmagic.ACMEManager, opts config.AutocertOptions) error {
366. 	if opts.EABKeyID != "" || opts.EABMACKey != "" {
367. 		acmeMgr.ExternalAccount = &acme.EAB{}
368. 	}
369. 	if opts.EABKeyID != "" {
370. 		acmeMgr.ExternalAccount.KeyID = opts.EABKeyID
371. 	}
372. 	if opts.EABMACKey != "" {
373. 		_, err := base64.RawURLEncoding.DecodeString(opts.EABMACKey)
374. 		if err != nil {
375. 			return fmt.Errorf("config: decoding base64-urlencoded MAC Key: %w", err)
376. 		}
377. 		acmeMgr.ExternalAccount.MACKey = opts.EABMACKey
378. 	}
379. 	return nil
380. }
381. 
382. // configureTrustedRoots configures the acmeMgr x509 roots to trust when communicating with an ACME CA.
383. func configureTrustedRoots(acmeMgr *certmagic.ACMEManager, opts config.AutocertOptions) error {
384. 	if opts.TrustedCA != "" {
385. 		// pool effectively contains the certificate(s) in the TrustedCA base64 PEM appended to the system roots
386. 		pool, err := cryptutil.GetCertPool(opts.TrustedCA, "")
387. 		if err != nil {
388. 			return fmt.Errorf("config: creating trusted certificate pool: %w", err)
389. 		}
390. 		acmeMgr.TrustedRoots = pool
391. 	}
392. 	if opts.TrustedCAFile != "" {
393. 		// pool effectively contains the certificate(s) in TrustedCAFile appended to the system roots
394. 		pool, err := cryptutil.GetCertPool("", opts.TrustedCAFile)
395. 		if err != nil {
396. 			return fmt.Errorf("config: creating trusted certificate pool: %w", err)
397. 		}
398. 		acmeMgr.TrustedRoots = pool
399. 	}
400. 	return nil
401. }
402. 
403. func sourceHostnames(cfg *config.Config) []string {
404. 	policies := cfg.Options.GetAllPolicies()
405. 
406. 	if len(policies) == 0 {
407. 		return nil
408. 	}
409. 
410. 	dedupe := map[string]struct{}{}
411. 	for _, p := range policies {
412. 		dedupe[p.Source.Hostname()] = struct{}{}
413. 	}
414. 	if cfg.Options.AuthenticateURLString != "" {
415. 		u, _ := cfg.Options.GetAuthenticateURL()
416. 		if u != nil {
417. 			dedupe[u.Hostname()] = struct{}{}
418. 		}
419. 	}
420. 
421. 	var h []string
422. 	for k := range dedupe {
423. 		h = append(h, k)
424. 	}
425. 	sort.Strings(h)
426. 
427. 	return h
428. }
429.

